// NewClientWithResponses creates a new ClientWithResponses, which wraps
// Client with return type handling
func NewClientWithResponses(server string, opts ...ClientOption) (*ClientWithResponses, error) {
	client, err := NewClient(server, opts...)
	if err != nil {
		return nil, err
	}
	return &ClientWithResponses{client}, nil
}

// WithBaseURL overrides the baseURL.
func WithBaseURL(baseURL string) ClientOption {
	return func(c *Client) error {
		newBaseURL, err := url.Parse(baseURL)
		if err != nil {
			return err
		}
		c.Server = newBaseURL.String()
		return nil
	}
}

// ClientWithResponsesInterface is the interface specification for the client with responses above.
type ClientWithResponsesInterface interface {

	// InterceptWithBodyWithResponse performs a POST /gateway/api/v1/intercept (the `Intercept` operationId) request,
	// with any type of body and a specified content type.
	//
	// Returns a wrapper object for the known response body format(s).
	InterceptWithBodyWithResponse(ctx context.Context, contentType string, body io.Reader, reqEditors ...RequestEditorFn) (*InterceptResponse, error)

	// InterceptWithResponse performs a POST /gateway/api/v1/intercept (the `Intercept` operationId) request.
	// Takes a body of the `application/json` content type, and returns a wrapper object for the known response body format(s).
	InterceptWithResponse(ctx context.Context, body InterceptJSONRequestBody, reqEditors ...RequestEditorFn) (*InterceptResponse, error)
}

type InterceptResponse struct {
	Body         []byte
	HTTPResponse *http.Response
	// JSON200 the response for an HTTP 200 `application/json` response
	JSON200 *struct {
		Payload InterceptDecision `json:"payload"`
	}
}

// GetJSON200 returns the response for an HTTP 200 `application/json` response
func (r InterceptResponse) GetJSON200() *struct {
	Payload InterceptDecision `json:"payload"`
} {
	return r.JSON200
}

// GetBody returns the raw response body bytes
func (r InterceptResponse) GetBody() []byte {
	return r.Body
}

// Status returns HTTPResponse.Status
func (r InterceptResponse) Status() string {
	if r.HTTPResponse != nil {
		return r.HTTPResponse.Status
	}
	return http.StatusText(0)
}

// StatusCode returns HTTPResponse.StatusCode
func (r InterceptResponse) StatusCode() int {
	if r.HTTPResponse != nil {
		return r.HTTPResponse.StatusCode
	}
	return 0
}

// ContentType is a convenience method to retrieve the Content-Type value from the HTTP response headers
func (r InterceptResponse) ContentType() string {
	if r.HTTPResponse != nil {
		return r.HTTPResponse.Header.Get("Content-Type")
	}
	return ""
}

// InterceptWithBodyWithResponse performs a POST /gateway/api/v1/intercept (the `Intercept` operationId) request,
// with any type of body and a specified content type.
//
// Returns a wrapper object for the known response body format(s).
func (c *ClientWithResponses) InterceptWithBodyWithResponse(ctx context.Context, contentType string, body io.Reader, reqEditors ...RequestEditorFn) (*InterceptResponse, error) {
	rsp, err := c.InterceptWithBody(ctx, contentType, body, reqEditors...)
	if err != nil {
		return nil, err
	}
	return ParseInterceptResponse(rsp)
}

// InterceptWithResponse performs a POST /gateway/api/v1/intercept (the `Intercept` operationId) request.
// Takes a body of the `application/json` content type, and returns a wrapper object for the known response body format(s).
func (c *ClientWithResponses) InterceptWithResponse(ctx context.Context, body InterceptJSONRequestBody, reqEditors ...RequestEditorFn) (*InterceptResponse, error) {
	rsp, err := c.Intercept(ctx, body, reqEditors...)
	if err != nil {
		return nil, err
	}
	return ParseInterceptResponse(rsp)
}

// ParseInterceptResponse parses an HTTP response from a InterceptWithResponse call
func ParseInterceptResponse(rsp *http.Response) (*InterceptResponse, error) {
	bodyBytes, err := io.ReadAll(rsp.Body)
	defer func() { _ = rsp.Body.Close() }()
	if err != nil {
		return nil, err
	}

	response := &InterceptResponse{
		Body:         bodyBytes,
		HTTPResponse: rsp,
	}

	switch {
	case strings.Contains(rsp.Header.Get("Content-Type"), "json") && rsp.StatusCode == 200:
		var dest struct {
			Payload InterceptDecision `json:"payload"`
		}
		if err := json.Unmarshal(bodyBytes, &dest); err != nil {
			return nil, err
		}
		response.JSON200 = &dest

	}

	return response, nil
}

